from __future__ import annotations

import dataclasses
import datetime as dt

import httpx2
import pytest
from ds.ai.model import seat_usage_tracked
from ds.data.raw.copilot import CopilotRefusedError, CopilotUsage, Quota
from ds.util.const import DEFAULT_AI_MODEL
from ui import copilot_usage

NOW = dt.datetime(2026, 11, 20, 10, 33, tzinfo=dt.UTC)
UNLIMITED = Quota(unlimited=True)


def _usage(used: float, limit: float = 7000, **more: object) -> CopilotUsage:
    premium = Quota(limit=limit, used=used, percent_used=100 * used / limit)
    fields = {"plan": "individual_pro", "resets": dt.date(2026, 12, 1), "unit": "credits", "premium": premium}
    return CopilotUsage(**(fields | more))


def test_the_meter_shows_a_percent_and_the_count_on_hover() -> None:
    meter = copilot_usage.build(_usage(22, chat=UNLIMITED, completions=UNLIMITED), NOW)
    assert (meter.percent, meter.detail) == ("<1%", "22 / 7,000 credits")
    assert (meter.resets, meter.as_of, meter.level) == ("resets 12/01", "11/20 10:33", "ok")
    assert meter.title.startswith("6,978 premium credits remaining · resets 2026-12-01 · Copilot plan: individual_pro")
    assert "chat: unlimited · completions: unlimited" in meter.title


@pytest.mark.parametrize(
    ("used", "percent", "level"),
    [(0, "0%", "ok"), (2800, "40%", "ok"), (5250, "75%", "warn"), (6300, "90%", "danger"), (7700, "110%", "danger")],
)
def test_the_bar_warns_as_the_quota_runs_out(used: float, percent: str, level: str) -> None:
    meter = copilot_usage.build(_usage(used), NOW)
    assert (meter.percent, meter.level) == (percent, level)
    assert float(meter.meter.rstrip("%")) <= 100  # the bar never overflows


def test_a_part_credit_is_shown_as_github_counts_it() -> None:
    meter = copilot_usage.build(_usage(35.5), NOW)
    assert meter.detail == "35.5 / 7,000 credits"
    assert meter.title.startswith("6,964.5 premium credits remaining")


def test_over_the_limit_says_by_how_much() -> None:
    assert copilot_usage.build(_usage(7700), NOW).title.startswith("700 premium credits over")


def test_an_unlimited_or_missing_premium_quota_has_no_percent() -> None:
    unlimited = copilot_usage.build(_usage(1, premium=Quota(used=12, unlimited=True), unit="requests"), NOW)
    assert (unlimited.percent, unlimited.detail, unlimited.level) == ("unlimited", "12 requests used", "")
    missing = copilot_usage.build(CopilotUsage(plan="business"), NOW)
    assert (missing.percent, missing.resets, missing.level) == ("unknown", "", "")
    assert "Copilot plan: business" in missing.title


@pytest.mark.parametrize(
    ("error", "problem"),
    [
        (CopilotRefusedError("GitHub refused (403: policy)"), "GitHub refused (403: policy)"),
        (httpx2.ConnectError("no route"), "GitHub couldn't be read (ConnectError)"),
    ],
)
def test_a_failed_read_is_returned_not_raised(monkeypatch: pytest.MonkeyPatch, error: Exception, problem: str) -> None:
    def refuse() -> CopilotUsage:
        raise error

    monkeypatch.setattr(copilot_usage, "copilot_usage", refuse)
    meter = copilot_usage.load()
    assert (meter.ok, meter.problem) == (False, problem)


def test_the_meter_is_on_the_page_for_a_copilot_model_only() -> None:
    assert copilot_usage.AVAILABLE is seat_usage_tracked(DEFAULT_AI_MODEL)
    assert seat_usage_tracked("github-copilot:gpt-5.6-luna") is True
    assert seat_usage_tracked("gateway/anthropic:claude-haiku-5-5") is False


def _headers(percent_left: float) -> dict[str, str]:
    value = f"ent=7000&ov=0.0&ovPerm=false&rem={percent_left}&rst=2026-12-01T00%3A00Z"
    return {"x-quota-snapshot-premium_interactions": value}


LATER = NOW + dt.timedelta(minutes=5)


def test_after_an_answer_its_cost_is_added_to_the_count_shown() -> None:
    shown = dataclasses.asdict(copilot_usage.build(_usage(35.5), NOW))
    meter = copilot_usage.from_answer(_headers(99.4), 4.5, shown, LATER)
    assert meter is not None
    assert (meter.percent, meter.detail) == ("<1%", "40 / 7,000 credits")  # exact, not "about"
    assert (meter.as_of, meter.plan, meter.unit) == ("11/20 10:38", "individual_pro", "credits")
    assert meter.title.startswith("6,960 premium credits remaining")
    # and the next answer adds to that
    again = copilot_usage.from_answer(_headers(99.4), 1.25, dataclasses.asdict(meter), LATER)
    assert again is not None
    assert again.detail == "41.2 / 7,000 credits"


def test_use_elsewhere_shows_as_the_headers_rounded_count() -> None:
    # the headers say 2% is gone (140) while the page adds up to 40: used elsewhere
    shown = dataclasses.asdict(copilot_usage.build(_usage(35.5), NOW))
    meter = copilot_usage.from_answer(_headers(98.0), 4.5, shown, LATER)
    assert meter is not None
    assert (meter.percent, meter.detail) == ("2%", "about 140 / 7,000 credits")
    assert "Copilot plan: individual_pro" in meter.title
    assert "refresh button reads the exact one" in meter.title


def test_with_nothing_read_yet_the_headers_fill_the_meter() -> None:
    # eg the usage request was refused: the first AI answer still says what is left
    blank = dataclasses.asdict(copilot_usage.CopilotMeter())
    meter = copilot_usage.from_answer(_headers(99.4), 4.5, blank, LATER)
    assert meter is not None
    assert (meter.percent, meter.detail) == ("<1%", "about 42 / 7,000 requests")


def test_an_answer_that_says_nothing_new_leaves_the_meter_alone() -> None:
    shown = dataclasses.asdict(copilot_usage.build(_usage(40), NOW))
    assert copilot_usage.from_answer({}, 4.5, shown, LATER) is None  # no quota headers
    assert copilot_usage.from_answer(_headers(99.4), 0, shown, LATER) is None  # no cost, same share
